#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the setup-wizard-generator skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
#

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-$HOME/.hermes/.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  •%s %s\n' "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  ↗ opening %s\n' "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s [Enter keeps current] ' "$BOLD" "$prompt" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s [Enter keeps current] ' "$BOLD" "$prompt" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  ✓ wrote %s → %s\n' "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  ✓ set GitHub secret %s\n' "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  ✓ set GitHub variable %s\n' "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'
    warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

banner "Hermes Agent Setup Wizard"

# ── Stage 1: Git Configuration ──
stage "Git Identity & Credentials"
say "Configure git identity and repository access credentials."
say "This is required for pushing to the TrioPrime repository."
confirm "Have you set your git identity? (user.name and user.email)"
open_url "https://github.com/settings/tokens/new?scopes=repo&description=Hermes-Agent-Setup"
step "Create a new GitHub personal access token with 'repo' scope"
ask_secret GIT_TOKEN "Paste your GitHub token (hidden entry):"
write_env GIT_TOKEN "$GIT_TOKEN"
confirm "Should we configure git with your identity?"
ask GIT_NAME "Your git name (e.g. Gökcan):"
ask GIT_EMAIL "Your git email (e.g. gokcan@trio.emlak):"
stage "Git Configuration Applied"
say "Applying git configuration..."
git config --global user.name "$GIT_NAME"
git config --global user.email "$GIT_EMAIL"
say "Git identity set: $GIT_NAME <$GIT_EMAIL>"

# ── Stage 2: NVIDIA AI API Setup ──
stage "NVIDIA AI API Key"
say "Configure NVIDIA AI API access for the Hermes agent."
say "The .env file already exists with basic NVIDIA configuration."
open_url "https://build.nvidia.com/settings/api-keys"
step "Visit NVIDIA Developer API Keys page and check current status"
ask_secret NVIDIA_API_KEY "Paste your NVIDIA API key (nvapi- format):"
ask NVIDIA_ORG_ID "Organization ID (e.g. org-3L39s67FauyJnLma5auZXT6clnY):"
write_env NVIDIA_API_KEY "$NVIDIA_API_KEY"
write_env NVIDIA_ORG_ID "$NVIDIA_ORG_ID"
say "NVIDIA API key and organization ID saved to .env"

# ── Stage 3: Brev API Validation ──
stage "Brev API Key Validation"
say "Validate Brev API access for model listing."
say "Current Brev API key needs validation (may show connection errors)."
confirm "Do you want to validate/replace the Brev API key?"
open_url "https://www.nvidia.com/en-us/ai-resources/brev/"
step "Navigate to Brev service and check API key status"
ask_secret BREV_API_KEY "Paste Brev API key (bak- format, or leave blank to skip):"
if [[ -n "$BREV_API_KEY" ]]; then
  write_env BREV_API_KEY "$BREV_API_KEY"
  say "Brev API key saved to .env"
else
  note "Skipping Brev API key - will use fallback NVIDIA API"
fi

# ── Stage 4: Project Dependencies ──
stage "Project Dependencies"
say "Verify Python environment and dependencies."
say "The project uses Python 3.14.8 with specific package requirements."
confirm "Have you activated the Python virtual environment?"
say "Checking for required packages..."
python3 -c "import nvidia_ai_client" 2>/dev/null && say "nvidia_ai_client module available" || say "nvidia_ai_client module may need installation"
say "Checking .env configuration..."
[[ -f "$ENV_FILE" ]] && say ".env file exists" || say ".env file missing - will be created"
step "Run: source venv/bin/activate or pip install -r requirements if needed"

# ── Stage 5: Git Remote & Repo Setup ──
stage "Git Remote & Repository"
say "Configure git remote for TrioPrime repository."
open_url "https://github.com/oserhan-svg/TrioPrime"
step "Verify repository owner is oserhan-svg (token account)"
confirm "Is the repository owner oserhan-svg?"
ask REMOTE_URL "Git remote URL (e.g. https://x-access-token:TOKEN@github.com/oserhan-svg/TrioPrime.git):"
git remote set-url origin "$REMOTE_URL" 2>/dev/null || git remote add origin "$REMOTE_URL"
say "Git remote configured: origin → $REMOTE_URL"
confirm "Test git connection with a fetch?"
git fetch --quiet 2>/dev/null && say "Git fetch successful" || warn "Git fetch may need credential setup"

# ── Stage 6: IDEA.md Verification ──
stage "IDEA.md Compliance Check"
say "Verify IDEA.md rules are properly configured."
say "Critical rules from IDEA.md that must be followed:"
say "  • DAİMA Ozancan Serhan (identity)"
say "  • DAİMA 0533 378 68 94 (phone number)"
say "  • Zero Halüsinasyon claim"
say "  • Region priority: Ayvalık/Cunda/Altınova/Gömeç/İstanbul"
confirm "Have you verified all IDEA.md rules are configured correctly?"
step "Review IDEA.md for: DAİMA Ozancan Serhan, DAİMA 0533 378 68 94"
say "IDEA.md compliance verification complete"

# ── Stage 7: Final Summary ──
stage "Setup Complete"
banner "Setup Summary"
note "All setup stages completed. Here's what was configured:"
(( ${#WRITTEN_ENV[@]} )) && note "  Environment variables written to $ENV_FILE: ${WRITTEN_ENV[*]}"
(( ${#WRITTEN_SECRET[@]} )) && note "  GitHub secrets set: ${WRITTEN_SECRET[*]}"
if (( ${#SKIPPED[@]} )); then
  printf '\n'
  warn "Items still pending manual setup:"
  for s in "${SKIPPED[@]}"; do note "  - $s"; done
fi
printf '\n'
finish